    for(const o of rows.Outbox) if(!['Succeeded','Cancelled'].includes(o.status)&&!(Number(o.attempt_count||0)===0&&!o.external_id&&o.status==='Pending')) task('S15-CAN-REVIEW','Outbox',o.id,'Reconcile uncertain normal send','Review');
